    function sectionHeight(section:any,compact?:boolean){if(section.kind==="chart")return compact?430:(section.chartStyle==="donut"?500:520);if(section.kind==="metric")return Math.min(410,84+Math.ceil(Math.min(8,(section.rows||[]).length)/2)*106);return Math.min(550,84+34*(Math.min(13,(section.rows||[]).length)+1));}
