    function flushPage(){if(!canvas||!ctx)return;ctx.fillStyle="#A0A2AA";ctx.font="13px Arial";ctx.textAlign="center";ctx.fillText("fAInance · "+todayStr(),pageW/2,pageH-31);ctx.textAlign="left";var data=canvas.toDataURL("image/jpeg",0.96).split(",")[1],raw=atob(data),arr=new Uint8Array(raw.length);for(var i=0;i<raw.length;i++)arr[i]=raw.charCodeAt(i);pages.push(arr);canvas=null;ctx=null;}
