    newPage();(sections||[]).forEach(function(section:any){var half=canUseHalfWidth(section),h=sectionHeight(section,half);if(half){if(!pendingHalf){if(y+h>contentBottom&&y>contentTop+20){flushPage();newPage();}drawSection(section,margin,y,halfW,h);pendingHalf=true;pendingHalfH=h;}else{drawSection(section,margin+halfW+columnGap,y,halfW,h);pendingHalfH=Math.max(pendingHalfH,h);finishHalfRow();}}else{finishHalfRow();if(y+h>contentBottom&&y>contentTop+20){flushPage();newPage();}drawSection(section,margin,y,contentW,h);y+=h+18;}});finishHalfRow();flushPage();if(!pages.length)return;
